// Asuka tech: behaviour of the custom blocks.
// Stable Script API only (@minecraft/server 2.0.0), no experimental toggles.
// Block definitions are generated by addon/pack/build.py.
import * as server from "@minecraft/server";
import { system, world, EquipmentSlot } from "@minecraft/server";

const NS = "asukatech";
const S = (name) => `${NS}:${name}`;

// Horizontal directions as {x, z}. A quarter turn follows the Bedrock wiki:
// +90 degrees turns north into west. Keep in step with TURN_SIGN in build.py.
const VEC = { north: { x: 0, z: -1 }, south: { x: 0, z: 1 }, east: { x: 1, z: 0 }, west: { x: -1, z: 0 } };
const turnLeft = (v) => ({ x: v.z, z: -v.x }); // +90: north -> west
const rotate = (v, quarters) => {
  let r = v;
  for (let i = 0; i < ((quarters % 4) + 4) % 4; i++) r = turnLeft(r);
  return r;
};
const SIDES = [
  { x: 1, y: 0, z: 0 }, { x: -1, y: 0, z: 0 }, { x: 0, y: 1, z: 0 },
  { x: 0, y: -1, z: 0 }, { x: 0, y: 0, z: 1 }, { x: 0, y: 0, z: -1 },
];

function state(block, name) {
  try {
    return block.permutation.getState(name);
  } catch {
    return undefined;
  }
}

function setStates(block, changes) {
  let perm = block.permutation;
  for (const [k, v] of Object.entries(changes)) perm = perm.withState(k, v);
  block.setPermutation(perm);
}

function sound(block, id) {
  try {
    block.dimension.playSound(id, block.center());
  } catch {
    // a missing sound is not worth an error
  }
}

// Redstone: the stable API has no "is this block powered" query for custom
// blocks, so look at the redstone power of the block and its neighbours
// (levers, buttons, torches, wire, redstone blocks). Approximate; needs a
// test in the game.
function powered(block) {
  if (!block || typeof block.getRedstonePower !== "function") return false;
  try {
    if ((block.getRedstonePower() ?? 0) > 0) return true;
    for (const d of SIDES) {
      const n = block.offset(d);
      if (n && (n.getRedstonePower() ?? 0) > 0) return true;
    }
  } catch {
    return false;
  }
  return false;
}

// ---------- doors ----------
// Two blocks: the lower half is the item; placing it puts the upper half on
// top. States: upper, open, hinge_right, powered (kept on the lower half).
const isDoor = (block) => block?.typeId.startsWith(`${NS}:door_`);

function doorHalves(block) {
  if (state(block, S("upper"))) return [block.below(), block];
  return [block, block.above()];
}

function setDoorOpen(lower, upper, open) {
  for (const half of [lower, upper]) {
    if (isDoor(half) && state(half, S("open")) !== open) setStates(half, { [S("open")]: open });
  }
  sound(lower, open ? "random.door_open" : "random.door_close");
}

function breakWithDrop(block) {
  const { x, y, z } = block.location;
  block.dimension.runCommand(`setblock ${x} ${y} ${z} air destroy`);
}

function onDoorBroken(e) {
  const perm = e.brokenBlockPermutation ?? e.destroyedBlockPermutation; // 2.0 name, then 1.x
  if (perm.getState(S("upper"))) {
    const lower = e.block.below();
    if (isDoor(lower) && !state(lower, S("upper"))) breakWithDrop(lower);
  } else {
    const upper = e.block.above();
    if (isDoor(upper) && state(upper, S("upper"))) upper.setType("minecraft:air");
  }
}

const DOOR = {
  beforeOnPlayerPlace(e) {
    const above = e.block.above();
    if (!above || !above.isAir) {
      e.cancel = true; // no room for the upper half
      return;
    }
    // Next to a door with its hinge on the far side: mirror the hinge, so the
    // two make a double door.
    const facing = e.permutationToPlace.getState("minecraft:cardinal_direction");
    const quarters = { south: 0, east: 1, north: 2, west: 3 }[facing] ?? 0;
    const hingeSide = rotate(VEC.west, quarters);
    const n = e.block.offset({ x: hingeSide.x, y: 0, z: hingeSide.z });
    if (isDoor(n) && !state(n, S("upper")) && state(n, "minecraft:cardinal_direction") === facing &&
        !state(n, S("hinge_right"))) {
      e.permutationToPlace = e.permutationToPlace.withState(S("hinge_right"), true);
    }
  },
  onPlace(e) {
    if (state(e.block, S("upper"))) return;
    const above = e.block.above();
    if (above && above.isAir) above.setPermutation(e.block.permutation.withState(S("upper"), true));
  },
  onPlayerInteract(e) {
    const [lower, upper] = doorHalves(e.block);
    if (!isDoor(lower)) return;
    setDoorOpen(lower, upper, !state(lower, S("open")));
  },
  onPlayerBreak: onDoorBroken,
  onPlayerDestroy: onDoorBroken, // the name before @minecraft/server 2.0
  onTick(e) {
    const b = e.block;
    if (state(b, S("upper"))) {
      const lower = b.below();
      if (!(lower?.typeId === b.typeId && !state(lower, S("upper")))) b.setType("minecraft:air");
      return;
    }
    const upper = b.above();
    if (!(upper?.typeId === b.typeId && state(upper, S("upper")))) {
      breakWithDrop(b); // the upper half is gone (explosion, piston): drop the door
      return;
    }
    const on = powered(b) || powered(upper);
    if (on !== state(b, S("powered"))) {
      setStates(b, { [S("powered")]: on });
      setDoorOpen(b, upper, on);
    }
  },
};

// ---------- trapdoors ----------
const TRAPDOOR = {
  onPlayerInteract(e) {
    const open = !state(e.block, S("open"));
    setStates(e.block, { [S("open")]: open });
    sound(e.block, open ? "random.door_open" : "random.door_close");
  },
  onTick(e) {
    const on = powered(e.block);
    if (on !== state(e.block, S("powered"))) {
      setStates(e.block, { [S("powered")]: on, [S("open")]: on });
      sound(e.block, on ? "random.door_open" : "random.door_close");
    }
  },
};

// ---------- takeaway coffee cup ----------
// Like sea pickles: use a cup on a cup block to add one, up to four.
const COFFEE_CUP = {
  onPlayerInteract(e) {
    const player = e.player;
    if (!player) return;
    const count = state(e.block, S("count")) ?? 1;
    if (count >= 4) return;
    const equip = player.getComponent("minecraft:equippable");
    const item = equip?.getEquipment(EquipmentSlot.Mainhand);
    if (item?.typeId !== e.block.typeId) return;
    setStates(e.block, { [S("count")]: count + 1 });
    sound(e.block, "use.wood");
    if (String(player.getGameMode()).toLowerCase() !== "creative") {
      if (item.amount > 1) {
        item.amount -= 1;
        equip.setEquipment(EquipmentSlot.Mainhand, item);
      } else {
        equip.setEquipment(EquipmentSlot.Mainhand, undefined);
      }
    }
  },
};

// ---------- conveyor body ----------
// A vanilla rail sits on top. Copy its shape into the body: shape (0 none,
// 1 straight, 2 curve, 3 slope) and turn (quarter turns of the model).
// The model draws a straight belt north-south, a curve joining south and
// east, and a slope rising toward the north.
const RAILS = new Set(["minecraft:rail", "minecraft:golden_rail", "minecraft:detector_rail", "minecraft:activator_rail"]);
// rail_direction: 0 north-south, 1 east-west, 2-5 ascending east, west,
// north, south, 6-9 curves south-east, south-west, north-west, north-east.
const RAIL_SHAPE = {
  0: [1, 0], 1: [1, 1],
  2: [3, 3], 3: [3, 1], 4: [3, 0], 5: [3, 2],
  6: [2, 0], 7: [2, 3], 8: [2, 2], 9: [2, 1],
};
const ASCENDING = { 2: VEC.east, 3: VEC.west, 4: VEC.north, 5: VEC.south };

function railDirection(block) {
  if (!block || !RAILS.has(block.typeId)) return undefined;
  return state(block, "rail_direction");
}

// The look a rail should have, from the block under it (a conveyor body or
// a coal block): shape, turn, and the caps. A slope rising into this rail
// from a side gets its top drawn here; that slope's rail is level with the
// block under this rail, one block over, and climbs toward this column.
function beltFor(base) {
  const dir = railDirection(base.above());
  const [shape, quarters] = dir === undefined ? [0, undefined] : RAIL_SHAPE[dir] ?? [0, 0];
  const q = quarters ?? state(base, S("turn")) ?? 0;
  const caps = { cap_s: false, cap_n: false, cap_e: false };
  for (const v of Object.values(VEC)) {
    const d = railDirection(base.offset({ x: v.x, y: 0, z: v.z }));
    const up = ASCENDING[d];
    if (!up || up.x !== -v.x || up.z !== -v.z) continue;
    const local = rotate(v, -q);
    if (local.z === 1) caps.cap_s = true;
    else if (local.z === -1) caps.cap_n = true;
    else if (local.x === 1) caps.cap_e = true;
  }
  return { [S("shape")]: shape, [S("turn")]: q, [S("cap_s")]: caps.cap_s,
           [S("cap_n")]: caps.cap_n, [S("cap_e")]: caps.cap_e };
}

const CONVEYOR = {
  onTick(e) {
    const want = beltFor(e.block);
    if (Object.entries(want).some(([k, v]) => state(e.block, k) !== v)) setStates(e.block, want);
  },
};

// ---------- rails on coal blocks look like conveyors ----------
// The conveyor's vanilla stand-in is a coal block under a vanilla rail. A
// rail on a coal block keeps both as they are (author's request,
// 2026-11-03): an entity that only draws the belt sits on the rail. It has
// no collision and takes no damage; the script adds and removes it. Without
// the add-on the entity is dropped and coal plus rail is the vanilla look.
const COAL = "minecraft:coal_block";
const BELT = S("belt");
const SCAN_RADIUS = 24;
const SCAN_HEIGHT = 8;
const key = (l) => `${l.x},${l.y},${l.z}`;

function syncBelts(player) {
  const BlockVolume = server.BlockVolume;
  const dim = player.dimension;
  if (!BlockVolume || typeof dim.getBlocks !== "function") return;
  const { min, max } = dim.heightRange;
  const p = player.location;
  const x = Math.floor(p.x), y = Math.floor(p.y), z = Math.floor(p.z);
  const from = { x: x - SCAN_RADIUS, y: Math.max(min + 1, y - SCAN_HEIGHT), z: z - SCAN_RADIUS };
  const to = { x: x + SCAN_RADIUS, y: Math.min(max - 1, y + SCAN_HEIGHT), z: z + SCAN_RADIUS };
  const inside = (l) => l.x >= from.x && l.x <= to.x && l.y >= from.y && l.y <= to.y && l.z >= from.z && l.z <= to.z;

  const want = new Map();
  const rails = dim.getBlocks(new BlockVolume(from, to), { includeTypes: [...RAILS] }, false);
  for (const loc of rails.getBlockLocationIterator()) {
    const below = dim.getBlock({ x: loc.x, y: loc.y - 1, z: loc.z });
    if (below?.typeId === COAL) want.set(key(loc), { loc, look: beltFor(below) });
  }
  const have = new Map();
  const reach = Math.hypot(SCAN_RADIUS, SCAN_RADIUS, SCAN_HEIGHT) + 2;
  for (const ent of dim.getEntities({ type: BELT, location: p, maxDistance: reach })) {
    const l = ent.location;
    const at = { x: Math.floor(l.x), y: Math.floor(l.y + 0.01), z: Math.floor(l.z) };
    if (!inside(at)) continue;
    const k = key(at);
    if (have.has(k) || !want.has(k)) {
      ent.remove(); // a duplicate, or the rail or coal is gone
      continue;
    }
    have.set(k, ent);
  }
  for (const [k, { loc, look }] of want) {
    let ent = have.get(k);
    if (!ent) {
      ent = dim.spawnEntity(BELT, { x: loc.x + 0.5, y: loc.y, z: loc.z + 0.5 });
      ent.setRotation({ x: 0, y: 0 });
    }
    for (const [name, v] of Object.entries(look)) {
      if (ent.getProperty(name) !== v) ent.setProperty(name, v);
    }
  }
}

function syncSafely(player) {
  try {
    syncBelts(player);
  } catch {
    // part of the area is not loaded
  }
}

// Right away when a player places or breaks something, and every 2 seconds
// for everything else (rails placed by commands or structures, old rails).
world.afterEvents.playerPlaceBlock.subscribe((e) => syncSafely(e.player));
world.afterEvents.playerBreakBlock.subscribe((e) => syncSafely(e.player));
system.runInterval(() => {
  for (const player of world.getAllPlayers()) syncSafely(player);
}, 40);

system.beforeEvents.startup.subscribe(({ blockComponentRegistry }) => {
  blockComponentRegistry.registerCustomComponent(S("door"), DOOR);
  blockComponentRegistry.registerCustomComponent(S("trapdoor"), TRAPDOOR);
  blockComponentRegistry.registerCustomComponent(S("coffee_cup"), COFFEE_CUP);
  blockComponentRegistry.registerCustomComponent(S("conveyor"), CONVEYOR);
});
